  "legal.eyebrow": "Juridiskt",
  "legal.last_updated": "Senast uppdaterad: {date}",
  "legal.banner.notice": "Denna översättning ges för din bekvämlighet. Den engelska versionen är den juridiskt auktoritativa texten.",
